double energy(int nbodies) {
  double e = 0.0;
  for (i=0; i<nbodies; i++) {
    Body &bi = bodies[i];
    e += bi.mass * (bi.vx*bi.vx + bi.vy*bi.vy + bi.vz*bi.vz);
    for (j=i+1; j<nbodies; j++) {
      Body &bj = bodies[j];
      double dx = bi.x - bj.x;
      ...
      double distance = sqrt(dx*dx + dy*dy + dz*dz);
      e -= (bi.mass * bj.mass) / distance;
    }
  }
  return 0.5 * e;
}
