/*
 * n-body — CLBG benchmark, TypeScript implementation.
 *
 * Simulates the Sun, Jupiter, Saturn, Uranus and Neptune with the
 * symplectic (semi-implicit Euler) integrator used by the benchmark
 * (dt = 0.01), starting from the initial conditions given in the CLBG
 * problem statement.  Prints the total system energy to nine decimal
 * places before and after the N integration timesteps.
 *
 * Usage: <prog> N
 */

const SOLAR_MASS = 4 * Math.PI * Math.PI;
const DAYS_PER_YEAR = 365.24;
const DT = 0.01;
const NBODIES = 5;

// Flat body layout: x, y, z, vx, vy, vz, mass  (7 doubles per body).
// Order: Sun, Jupiter, Saturn, Uranus, Neptune.

/** Total energy of the system (kinetic + pairwise potential). */
function energy(b: Float64Array): number {
  let e = 0;
  for (let i = 0; i < NBODIES; i++) {
    const o = i * 7;
    const mi = b[o + 6];
    const vxi = b[o + 3];
    const vyi = b[o + 4];
    const vzi = b[o + 5];
    e += 0.5 * mi * (vxi * vxi + vyi * vyi + vzi * vzi);
    for (let j = i + 1; j < NBODIES; j++) {
      const p = j * 7;
      const dx = b[o] - b[p];
      const dy = b[o + 1] - b[p + 1];
      const dz = b[o + 2] - b[p + 2];
      e -= (mi * b[p + 6]) / Math.sqrt(dx * dx + dy * dy + dz * dz);
    }
  }
  return e;
}

