```typescript
function advance(b: Float64Array): void {
  // Load positions and velocities
  let x1=b[0], y1=b[1], z1=b[2], vx1=b[3], vy1=b[4], vz1=b[5], m1=b[6];
  let x2=b[7], y2=b[8], z2=b[9], vx2=b[10], vy2=b[11], vz2=b[12], m2=b[13];
  let x3=b[14], y3=b[15], z3=b[16], vx3=b[17], vy3=b[18], vz3=b[19], m3=b[20];
  let x4=b[21], y4=b[22], z4=b[23], vx4=b[24], vy4=b[25], vz4=b[26], m4=b[27];
  let x5=b[28], y5=b[29], z5=b[30], vx5=b[31], vy5=b[32], vz5=b[33], m5=b[34];

  const dt = DT;

  // Pair 1-2
  {
    let dx = x1 - x2, dy = y1 - y2, dz = z1 - z2;
    let d2 = dx*dx + dy*dy + dz*dz;
    let mag = dt / (d2 * Math.sqrt(d2));
    const bm2 = m2 * mag, bm1 = m1 * mag;
    vx1 -= dx * bm2; vy1 -= dy * bm2; vz1 -= dz * bm2;
    vx2 += dx * bm1; vy2 += dy * bm1; vz2 += dz * bm1;
  }
  // ... pairs 1-3, 1-4, 1-5, 2-3, 2-4, 2-5, 3-4, 3-5, 4-5

  // Update positions
  x1 += dt * vx1; ...

  // Store back
  b[0] = x1; ...
}
```

