```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define pi 3.141592653589793
#define solarmass 4*pi*pi
#define daysperyear 365.24

typedef struct { double x,y,z,vx,vy,vz,mass; } body;

static void offsetmomentum(body *bodies, int n) {
   double px=0, py=0, pz=0;
   for (int i=0; i<n; i++) {
      px += bodies[i].vx * bodies[i].mass;
      py += bodies[i].vy * bodies[i].mass;
      pz += bodies[i].vz * bodies[i].mass;
   }
   bodies[0].vx = -px/solarmass;
   bodies[0].vy = -py/solarmass;
   bodies[0].vz = -pz/solarmass;
}

static void advance(body *bodies, int n, double dt) {
   for (int i=0; i<n; i++) {
      body *bi = &bodies[i];
      for (int j=i+1; j<n; j++) {
         body *bj = &bodies[j];
         double dx = bi->x - bj->x;
         double dy = bi->y - bj->y;
         double dz = bi->z - bj->z;
         double d2 = dx*dx + dy*dy + dz*dz;
         double mag = dt / (d2 * sqrt(d2));
         bi->vx -= dx * bj->mass * mag;
         bi->vy -= dy * bj->mass * mag;
         bi->vz -= dz * bj->mass * mag;
         bj->vx += dx * bi->mass * mag;
         bj->vy += dy * bi->mass * mag;
         bj->vz += dz * bi->mass * mag;
      }
   }
   for (int i=0; i<n; i++) {
      body *b = &bodies[i];
      b->x += dt * b->vx;
      b->y += dt * b->vy;
      b->z += dt * b->vz;
   }
}

static double energy(body *bodies, int n) {
   double e = 0;
   for (int i=0; i<n; i++) {
      body *bi = &bodies[i];
      e += 0.5 * bi->mass * (bi->vx*bi->vx + bi->vy*bi->vy + bi->vz*bi->vz);
      for (int j=i+1; j<n; j++) {
         body *bj = &bodies[j];
         double dx = bi->x - bj->x;
         double dy = bi->y - bj->y;
         double dz = bi->z - bj->z;
         double distance = sqrt(dx*dx + dy*dy + dz*dz);
         e -= (bi->mass * bj->mass) / distance;
      }
   }
   return e;
}

int main(int argc, char **argv) {
   int n = atoi(argv[1]);
   body bodies[5] = { ... };
   offsetmomentum(bodies, 5);
   printf("%.9f\n", energy(bodies, 5));
   for (int i=0; i<n; i++) advance(bodies, 5, 0.01);
   printf("%.9f\n", energy(bodies, 5));
   return 0;
}
```

