/*
 * n-body — CLBG benchmark, TypeScript implementation.
 *
 * Simulates Jupiter, Saturn, Uranus, Neptune and the Sun using the
 * symplectic (semi-implicit) Euler method with dt = 0.01, starting from
 * the J2000 initial conditions used by the CLBG problem statement.
 *
 * Usage: <prog> N
 * Prints the total system energy (9 decimal places) before and after
 * the N integration steps.
 */

const SOLAR_MASS = 4 * Math.PI * Math.PI;
const DAYS_PER_YEAR = 365.24;
const DT = 0.01;
const NBODIES = 5;

/** Total energy of the system: kinetic + potential (pairwise). */
function energy(b: Float64Array): number {
  let e = 0;
  for (let i = 0; i < NBODIES; i++) {
    const o = i * 7;
    const mi = b[o + 6];
    const vxi = b[o + 3];
    const vyi = b[o + 4];
    const vzi = b[o + 5];
    e += mi * (vxi * vxi + vyi * vyi + vzi * vzi);
    for (let j = i + 1; j < NBODIES; j++) {
      const p = j * 7;
      const dx = b[o] - b[p];
      const dy = b[o + 1] - b[p + 1];
      const dz = b[o + 2] - b[p + 2];
      e -= (mi * b[p + 6]) / Math.sqrt(dx * dx + dy * dy + dz * dz);
    }
  }
  return 0.5 * e;
}

/** Advance the system by nSteps symplectic Euler steps of size DT. */
function advance(nSteps: number, b: Float64Array): void {
  // Load all bodies into local variables (hot loop works on registers).
  let x1 = b[0], y1 = b[1], z1 = b[2];
  let vx1 = b[3], vy1 = b[4], vz1 = b[5];
  const m1 = b[6];

  let x2 = b[7], y2 = b[8], z2 = b[9];
  let vx2 = b[10], vy2 = b[11], vz2 = b[12];
  const m2 = b[13];

  let x3 = b[14], y3 = b[15], z3 = b[16];
  let vx3 = b[17], vy3 = b[18], vz3 = b[19];
  const m3 = b[20];

  let x4 = b[21], y4 = b[22], z4 = b[23];
  let vx4 = b[24], vy4 = b[25], vz4 = b[26];
  const m4 = b[27];

  let x5 = b[28], y5 = b[29], z5 = b[30];
  let vx5 = b[31], vy5 = b[32], vz5 = b[33];
  const m5 = b[34];

  for (let step = 0; step < nSteps; step++) {
    // Pair (1,2)
    let dx = x1 - x2, dy = y1 - y2, dz = z1 - z2;
    let d2 = dx * dx + dy * dy + dz * dz;
    let mag = DT / (d2 * Math.sqrt(d2));
    vx1 -= dx * m2 * mag; vy1 -= dy * m2 * mag; vz1 -= dz * m2 * mag;
    vx2 += dx * m1 * mag; vy2 += dy * m1 * mag; vz2 += dz * m1 * mag;

    // Pair (1,3)
    dx = x1 - x3; dy = y1 - y3; dz = z1 - z3;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx1 -= dx * m3 * mag; vy1 -= dy * m3 * mag; vz1 -= dz * m3 * mag;
    vx3 += dx * m1 * mag; vy3 += dy * m1 * mag; vz3 += dz * m1 * mag;

    // Pair (1,4)
    dx = x1 - x4; dy = y1 - y4; dz = z1 - z4;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx1 -= dx * m4 * mag; vy1 -= dy * m4 * mag; vz1 -= dz * m4 * mag;
    vx4 += dx * m1 * mag; vy4 += dy * m1 * mag; vz4 += dz * m1 * mag;

    // Pair (1,5)
    dx = x1 - x5; dy = y1 - y5; dz = z1 - z5;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx1 -= dx * m5 * mag; vy1 -= dy * m5 * mag; vz1 -= dz * m5 * mag;
    vx5 += dx * m1 * mag; vy5 += dy * m1 * mag; vz5 += dz * m1 * mag;

    // Pair (2,3)
    dx = x2 - x3; dy = y2 - y3; dz = z2 - z3;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx2 -= dx * m3 * mag; vy2 -= dy * m3 * mag; vz2 -= dz * m3 * mag;
    vx3 += dx * m2 * mag; vy3 += dy * m2 * mag; vz3 += dz * m2 * mag;

    // Pair (2,4)
    dx = x2 - x4; dy = y2 - y4; dz = z2 - z4;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx2 -= dx * m4 * mag; vy2 -= dy * m4 * mag; vz2 -= dz * m4 * mag;
    vx4 += dx * m2 * mag; vy4 += dy * m2 * mag; vz4 += dz * m2 * mag;

    // Pair (2,5)
    dx = x2 - x5; dy = y2 - y5; dz = z2 - z5;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx2 -= dx * m5 * mag; vy2 -= dy * m5 * mag; vz2 -= dz * m5 * mag;
    vx5 += dx * m2 * mag; vy5 += dy * m2 * mag; vz5 += dz * m2 * mag;

    // Pair (3,4)
    dx = x3 - x4; dy = y3 - y4; dz = z3 - z4;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx3 -= dx * m4 * mag; vy3 -= dy * m4 * mag; vz3 -= dz * m4 * mag;
    vx4 += dx * m3 * mag; vy4 += dy * m3 * mag; vz4 += dz * m3 * mag;

    // Pair (3,5)
    dx = x3 - x5; dy = y3 - y5; dz = z3 - z5;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx3 -= dx * m5 * mag; vy3 -= dy * m5 * mag; vz3 -= dz * m5 * mag;
    vx5 += dx * m3 * mag; vy5 += dy * m3 * mag; vz5 += dz * m3 * mag;

    // Pair (4,5)
    dx = x4 - x5; dy = y4 - y5; dz = z4 - z5;
    d2 = dx * dx + dy * dy + dz * dz;
    mag = DT / (d2 * Math.sqrt(d2));
    vx4 -= dx * m5 * mag; vy4 -= dy * m5 * mag; vz4 -= dz * m5 * mag;
    vx5 += dx * m4 * mag; vy5 += dy * m4 * mag; vz5 += dz * m4 * mag;

    // Update positions
    x1 += DT * vx1; y1 += DT * vy1; z1 += DT * vz1;
    x2 += DT * vx2; y2 += DT * vy2; z2 += DT * vz2;
    x3 += DT * vx3; y3 += DT * vy3; z3 += DT * vz3;
    x4 += DT * vx4; y4 += DT * vy4; z4 += DT * vz4;
    x5 += DT * vx5; y5 += DT * vy5; z5 += DT * vz5;
  }

