  b[0] = x1; b[1] = y1; b[2] = z1; b[3] = vx1; b[4] = vy1; b[5] = vz1;
  b[7] = x2; b[8] = y2; b[9] = z2; b[10] = vx2; b[11] = vy2; b[12] = vz2;
  b[14] = x3; b[15] = y3; b[16] = z3; b[17] = vx3; b[18] = vy3; b[19] = vz3;
  b[21] = x4; b[22] = y4; b[23] = z4; b[24] = vx4; b[25] = vy4; b[26] = vz4;
  b[28] = x5; b[29] = y5; b[30] = z5; b[31] = vx5; b[32] = vy5; b[33] = vz5;
}

