  const pair = (a: string, b: string): void => {
    comp[a.charCodeAt(0)] = b.charCodeAt(0);
    comp[b.charCodeAt(0)] = a.charCodeAt(0);
  };
  pair('A', 'T');
  pair('C', 'G');
  pair('R', 'Y');
  pair('K', 'M');
  pair('B', 'V');
  pair('D', 'H');
  comp['U'.charCodeAt(0)] = 'A'.charCodeAt(0); // U -> A (one-way)
  // lowercase equivalents
  pair('a', 't');
  pair('c', 'g');
  pair('r', 'y');
  pair('k', 'm');
  pair('b', 'v');
  pair('d', 'h');
  comp['u'.charCodeAt(0)] = 'a'.charCodeAt(0);

  const inp = new Uint8Array(input.buffer, input.byteOffset, len);
  const out = Buffer.allocUnsafe(len + 1); // +1 in case input lacks final '\n'
  const outB = new Uint8Array(out.buffer, out.byteOffset, len + 1);
  let outPos = 0;

  // Start offsets of the sequence lines of the block currently buffered.
  let starts = new Int32Array(1 << 16);
  let startsLen = 0;
  let lastLineEnd = 0; // exclusive end of the newest buffered line's content

  // Emit the buffered block: lines in reverse order, each line reversed and
  // complemented, every emitted line terminated with '\n'.
  const flush = (): void => {
    for (let k = startsLen - 1; k >= 0; k--) {
      const s = starts[k];
