  const c = (ch: string): number => ch.charCodeAt(0);
  const setPair = (a: number, b: number): void => {
    table[a] = b;
    table[b] = a;
  };
  setPair(c('A'), c('T'));
  setPair(c('C'), c('G'));
  setPair(c('R'), c('Y'));
  setPair(c('K'), c('M'));
  setPair(c('B'), c('V'));
  setPair(c('D'), c('H'));
  table[c('U')] = c('A');
  setPair(c('a'), c('t'));
  setPair(c('c'), c('g'));
  setPair(c('r'), c('y'));
  setPair(c('k'), c('m'));
  setPair(c('b'), c('v'));
  setPair(c('d'), c('h'));
  table[c('u')] = c('a');
  // S, W, N (and lowercase s, w, n) complement to themselves (identity default).

  const inp = new Uint8Array(input.buffer, input.byteOffset, len);
  const out = Buffer.allocUnsafe(len);
  const outU = new Uint8Array(out.buffer, out.byteOffset, len);
  let outPos = 0;

  // Stack of sequence-line start offsets for the current block.
  let starts = new Int32Array(1 << 12);
  let startsLen = 0;
  let lastLineEnd = 0;   // exclusive end of the most recent sequence line's content
  let lastHadNl = false;

  const flush = (blockEnd: number): void => {
    for (let k = startsLen - 1; k >= 0; k--) {
      const s = starts[k];
      const e = k === startsLen - 1 ? lastLineEnd : starts[k + 1] - 1;
      let p = e - 1;
      while (p >= s) {
        outU[outPos++] = table[inp[p]];
        p--;
      }
      outU[outPos++] = 10;
    }
    startsLen = 0;
  };

  let i = 0;
  while (i < len) {
    let nl = inp.indexOf(10, i);
    if (nl === -1) nl = len;
    const b0 = inp[i];
    if (b0 === 62 /* > */ || b0 === 59 /* ; */) {
      if (startsLen > 0) flush(nl);
      const e = nl < len ? nl + 1 : len;
      // copy header line verbatim
      for (let p = i; p < e; p++) outU[outPos++] = inp[p];
      // (or input.copy(out, outPos, i, e); outPos += e - i;)
