        const grown = new Int32Array(starts.length << 1);
        grown.set(starts);
        starts = grown;
      }
      starts[startsLen++] = i;
      lastLineEnd = nl;
      lastHadNl = nl < len;
    }
    i = nl + 1;
  }
  if (startsLen > 0) flush(len);

  let written = 0;
  while (written < outPos) {
    written += writeSync(1, out, written, outPos - written);
  }
  void nArg;
}

main();
