  const out = Buffer.allocUnsafe(len + 1);
  const outU = new Uint8Array(out.buffer, out.byteOffset, len + 1);
  let outPos = 0;

  // Stack of start offsets of sequence lines in the current block.
  let starts = new Int32Array(1 << 16);
  let startsLen = 0;
  let lastLineEnd = 0; // exclusive end of content of the newest sequence line
  let lastHadNl = false;

  const flush = (): void => {
    for (let k = startsLen - 1; k >= 0; k--) {
      const s = starts[k];
      const e = k === startsLen - 1 ? lastLineEnd : starts[k + 1] - 1;
      let p = e;
      while (p > s) outU[outPos++] = table[inp[--p]];
      outU[outPos++] = 10;
