    let nl = inp.indexOf(10, i);
    if (nl < 0) nl = len;
    const b0 = inp[i];
    if (b0 === 62 || b0 === 59) {
      // '>' or ';' -> header/comment line: flush pending block, copy verbatim.
      if (startsLen > 0) flush();
      const e = nl < len ? nl + 1 : len;
      input.copy(out, outPos, i, e);
      outPos += e - i;
    } else {
      if (startsLen === starts.length) {
        const grown = new Int32Array(starts.length << 1);
        grown.set(starts);
        starts = grown;
      }
      starts[startsLen++] = i;
      lastLineEnd = nl;
      lastHadNl = nl < len;
    }
    i = nl + 1;
  }
  if (startsLen > 0) flush();

  // Emit everything (handling possible partial writes on pipes).
  let written = 0;
  const total = outPos;
  while (written < total) {
    written += writeSync(1, out, written, total - written);
