```typescript
/*
 * reverse-complement
 *
 * Reads FASTA-formatted DNA from stdin and writes the reverse complement of
 * every sequence to stdout, preserving each header line verbatim and keeping
 * the original line wrapping (sequence lines are emitted in reverse order,
 * each line reversed and complemented, which is the canonical FASTA
 * reverse-complement layout).
 *
 * The whole input is read into memory once, transformed with a single
 * 256-entry complement lookup table, and written out with synchronous writes
 * that tolerate partial writes on pipes.
 */

import { readFileSync, writeSync } from 'fs';

function main(): void {
  // Harness contract: N arrives as the first CLI argument. It only sizes the
  // generated stdin data, so it is parsed (and intentionally unused here).
  const n = parseInt(process.argv[2] as string, 10);
  void n;

  const input = readFileSync(0);
  const len = input.length;
  if (len === 0) return;

  // ---------------------------------------------------------------- tables
  const comp = new Uint8Array(256);
  for (let b = 0; b < 256; b++) comp[b] = b; // identity: newlines, S, W, N, ...
  const pair = (a: string, b: string): void => {
    comp[a.charCodeAt(0)] = b.charCodeAt(0);
    comp[b.charCodeAt(0)] = a.charCodeAt(0);
  };
  pair('A', 'T');
  pair('C', 'G');
  pair('R', 'Y');
  pair('K', 'M');
  pair('B', 'V');
  pair('D', 'H');
  comp['U'.charCodeAt(0)] = 'A'.charCodeAt(0); // U -> A (one-way)
  // lowercase equivalents
  pair('a', 't');
  pair('c', 'g');
  pair('r', 'y');
  pair('k', 'm');
  pair('b', 'v');
  pair('d', 'h');
  comp['u'.charCodeAt(0)] = 'a'.charCodeAt(0);

  // ---------------------------------------------------------------- state
  const inp = new Uint8Array(input.buffer, input.byteOffset, len);
  const out = Buffer.allocUnsafe(len + 1); // +1: input may lack a final newline
  const outB = new Uint8Array(out.buffer, out.byteOffset, len + 1);
  let outPos = 0;

  // Start offsets of the sequence lines of the block currently being read.
  let starts = new Int32Array(1 << 16);
  let startsLen = 0;
  let lastLineEnd = 0; // exclusive end of the newest sequence line's content

  // Emit the pending block: lines in reverse order, each line reversed and
  // complemented, every output line terminated with '\n'.
  const flush = (): void => {
    for (let k = startsLen - 1; k >= 0; k--) {
      const s = starts[k];
      const e = k === startsLen - 1 ? lastLineEnd : starts[k + 1] - 1;
      let p = e;
      while (p > s) outB[outPos++] = comp[inp[--p]];
      outB[outPos++] = 10; // '\n'
    }
    startsLen = 0;
  };

  // ---------------------------------------------------------------- scan
  let i = 0;
  while (i < len) {
    let nl = inp.indexOf(10, i); // end of this line (index of '\n')
    if (nl < 0) nl = len;        // last line without trailing newline
    const b0 = inp[i];
    if (b0 === 62 /* '>' */ || b0 === 59 /* ';' */) {
      if (startsLen > 0) flush();
      const e = nl < len ? nl + 1 : len;
      input.copy(out, outPos, i, e); // header line verbatim
      outPos += e - i;
    } else {
      if (startsLen === starts.length) {
        const grown = new Int32Array(starts.length << 1);
        grown.set(starts);
        starts = grown;
      }
      starts[startsLen++] = i;
      lastLineEnd = nl;
    }
    i = nl + 1;
  }
  if (startsLen > 0) flush();

  // ---------------------------------------------------------------- emit
  let written = 0;
  while (written < outPos) {
    written += writeSync(1, out, written, outPos - written);
  }
}

main();
