// reverse-complement — FASTA reverse complement with preserved headers and
// line wrapping. Reads all of stdin, transforms in memory, writes to stdout.

import { readFileSync, writeSync } from 'fs';

function main(): void {
  // Harness passes N as the first CLI argument; it only sizes the piped
  // stdin data, so it is parsed per the contract but does not alter output.
  const n = parseInt(process.argv[2] as string, 10);
  void n;

  const input = readFileSync(0);
  const len = input.length;
  if (len === 0) return;

  // 256-entry IUPAC complement table; identity for everything else
  // (newlines, S, W, N, unknown bytes).
  const comp = new Uint8Array(256);
  for (let b = 0; b < 256; b++) comp[b] = b;
  const pair = (a: string, b: string): void => {
    comp[a.charCodeAt(0)] = b.charCodeAt(0);
    comp[b.charCodeAt(0)] = a.charCodeAt(0);
  };
  pair('A', 'T');
  pair('C', 'G');
  pair('R', 'Y');
  pair('K', 'M');
  pair('B', 'V');
  pair('D', 'H');
  comp['U'.charCodeAt(0)] = 'A'.charCodeAt(0); // U -> A (one-way)
  pair('a', 't');
  pair('c', 'g');
  pair('r', 'y');
  pair('k', 'm');
  pair('b', 'v');
  pair('d', 'h');
  comp['u'.charCodeAt(0)] = 'a'.charCodeAt(0);

  const inp = new Uint8Array(input.buffer, input.byteOffset, len);
  const out = Buffer.allocUnsafe(len + 1); // +1 in case input lacks final '\n'
  const outB = new Uint8Array(out.buffer, out.byteOffset, len + 1);
  let outPos = 0;

  // Start offsets of the sequence lines of the block currently buffered.
  let starts = new Int32Array(1 << 16);
  let startsLen = 0;
  let lastLineEnd = 0; // exclusive end of the newest buffered line's content

  // Emit the buffered block: lines in reverse order, each line reversed and
  // complemented, every emitted line terminated with '\n'.
  const flush = (): void => {
    for (let k = startsLen - 1; k >= 0; k--) {
      const s = starts[k];
      const e = k === startsLen - 1 ? lastLineEnd : starts[k + 1] - 1;
      let p = e;
      while (p > s) outB[outPos++] = comp[inp[--p]];
      outB[outPos++] = 10; // '\n'
    }
    startsLen = 0;
  };

  let i = 0;
  while (i < len) {
    let nl = inp.indexOf(10, i); // index of this line's '\n'
    if (nl < 0) nl = len;        // final line without trailing newline
    const b0 = inp[i];
    if (b0 === 62 /* '>' */ || b0 === 59 /* ';' */) {
      // Header/comment line: flush the pending sequence block, then copy
      // the header verbatim (including its newline).
      if (startsLen > 0) flush();
      const e = nl < len ? nl + 1 : len;
      input.copy(out, outPos, i, e);
      outPos += e - i;
    } else {
      if (startsLen === starts.length) {
        const grown = new Int32Array(starts.length << 1);
        grown.set(starts);
        starts = grown;
      }
      starts[startsLen++] = i;
      lastLineEnd = nl;
    }
    i = nl + 1;
  }
  if (startsLen > 0) flush();

  // Write everything, tolerating partial writes on pipes.
  let written = 0;
  while (written < outPos) {
    written += writeSync(1, out, written, outPos - written);
  }
}

main();
```

